       */
      grid.value = true;
      if (!prompt_to_use_existing_spatial.value) {
        roi.value.loadTixels(tissue_position.value);
      } else {
        roi.value.loadTixels(count_position.value);
        create_color_var();
      }
    }
    function show_grid() {
      /**
       * Method to show the grid.
       */
      grid.value = true;
